// Package kernelfixtures locates the cost model's scenario fixtures, which this repository
// holds under testdata/kernel/ (release plan §2: they are scenarios with engine blocks, so they
// need an engine to lower them, and only inference-sim imports both the engine and the cost
// model).
//
// testdata/kernel/aisimulate/ and testdata/kernel/direct/ are generated by the scripts under
// scripts/kernel/; the files directly under testdata/kernel/ are written by hand.
package kernelfixtures

import (
	"path/filepath"
	"runtime"
)

// Root is testdata/kernel/ in this repository, located from this file's compiled-in path, so
// tests in every package directory, and go run from any working directory, find the same
// files. self is <repo>/internal/kernelfixtures/kernelfixtures.go.
func Root() string {
	_, self, _, ok := runtime.Caller(0)
	if !ok {
		panic("kernelfixtures: no caller information to locate testdata/kernel")
	}
	return filepath.Join(filepath.Dir(filepath.Dir(filepath.Dir(self))), "testdata", "kernel")
}

// AISimulate is the directory of fixtures generated from AISimulate's end-to-end corpus, which
// the simulator's kernel tests open.
func AISimulate() string { return filepath.Join(Root(), "aisimulate") }

// Direct is the directory of fixtures generated from the InferenceX direct corpus.
func Direct() string { return filepath.Join(Root(), "direct") }
